import{_ as t,o,c as a,a5 as s}from"./chunks/framework.BfQ7H7Qx.js";const m=JSON.parse('{"title":"FR 3.6.8 — View Task Filter","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/05-content-task-workflow/3-6-8-view-task-filter/spec.md","filePath":"feature/srs/05-content-task-workflow/3-6-8-view-task-filter/spec.md"}'),r={name:"feature/srs/05-content-task-workflow/3-6-8-view-task-filter/spec.md"};function i(n,e,c,d,l,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-6-8-—-view-task-filter" tabindex="-1">FR 3.6.8 — View Task Filter <a class="header-anchor" href="#fr-3-6-8-—-view-task-filter" aria-label="Permalink to &quot;FR 3.6.8 — View Task Filter&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.6.8</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-060</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">View Task Filter</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Content &amp; Workflow (<code>FR 3.6</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20, BR-33</code></td></tr><tr><td style="text-align:left;"><strong>Document Status</strong></td><td style="text-align:left;">Implemented &amp; Verified</td></tr></tbody></table><h2 id="_1-objective-functional-scope" tabindex="-1">1. Objective &amp; Functional Scope <a class="header-anchor" href="#_1-objective-functional-scope" aria-label="Permalink to &quot;1. Objective &amp; Functional Scope&quot;">​</a></h2><p>Tìm kiếm, lọc đa tiêu chí và sắp xếp dữ liệu công việc xuyên suốt cả 4 chế độ xem List, Calendar, Gantt và Kanban (View Task Filter — /workspaces/:id/tasks). Tham khảo cơ chế lọc chi tiết của Jira: hỗ trợ tìm theo từ khóa tiêu đề/mô tả và lọc kết hợp theo Trạng thái, Người phụ trách (Assignee), Chiến dịch (Campaign), Nền tảng, Mức độ ưu tiên, Nhãn (Tag) và Khoảng thời gian.</p><p><strong>Consolidated Implementation Scope:</strong> Executes server-side <code>AND</code>-combined MongoDB filtering (<code>status</code>, <code>type</code>, literal escaped <code>search</code> on title/description, <code>campaignId</code>, <code>assignee</code>, <code>due</code> overdue/upcoming presets, <code>from</code>/<code>to</code> instants, and whitelisted <code>sort</code> keys) synchronized into URL query parameters (powering direct drill-down links from Role-Based Dashboards) and persisted across List, Kanban, Calendar, and Timeline switches.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized actor (<code>Owner, Manager, Creator, Client</code>), I want to execute <strong>View Task Filter</strong> within my active Workspace with strict role/audience isolation, version/concurrency safety, and responsive feedback, so that content production workflows satisfy <code>BR-20, BR-33</code> across Web and Mobile.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Workspace &amp; Role Authorization:</strong> Only authenticated actors holding <code>Owner, Manager, Creator, Client</code> in the target Workspace (plus <code>Guest</code> solely on public survey token endpoints in <code>3.6.25</code>) may invoke <code>GET /api/v1/workspaces/{workspaceId}/tasks?status=&amp;type=&amp;search=&amp;campaignId=&amp;from=&amp;to=&amp;assignee=&amp;due=&amp;sort=&amp;direction=&amp;page=&amp;size=</code>; revoked or cross-workspace callers are rejected (<code>401</code> / <code>403</code>).</li><li><strong>Core Domain &amp; Security Invariants (<code>BR-20, BR-33</code>):</strong> <code>TaskServiceImpl, WorkspaceTaskReader (</code>TaskListQuery<code>)</code> enforces all state-machine locks, audience visibility filters (<code>INTERNAL</code> vs per-<code>clientProfileId</code> <code>CLIENT</code>), storage/file validation rules, and Workspace timezone boundaries (<code>Asia/Ho_Chi_Minh</code> default).</li><li><strong>Persistence &amp; Envelope Contract:</strong> Operations on MongoDB <code>tasks</code> (compound indexes on <code>workspaceId + status + type + assigneeId + dueDate + createdAt</code>) return standardized <code>ApiResponse&lt;T&gt;</code> payloads (or authenticated binary/WebSocket frames where applicable) with deterministic <code>ErrorCode</code> mappings (<code>400 VALIDATION_ERROR</code> (invalid ISO date / page bounds), <code>403 WORKSPACE_ACCESS_DENIED</code>).</li><li><strong>Internationalization (<code>vi</code> / <code>en</code>):</strong> Every label, badge, filter pill, modal prompt, empty state, and error toast uses parallel translation keys (<code>tasks.filters.*</code>) in <code>src/i18n/locales/vi/*.json</code> and <code>en/*.json</code> — zero hardcoded UI text.</li><li><strong>Semantic Light/Dark Theme &amp; Accessibility:</strong> Web (<code>src/pages/tasks/components/{TaskFilterBar,TaskCategoryBar,TaskMultiSelectFilter}.tsx</code>, <code>src/pages/tasks/hooks/{useTaskFilters,useFilterCategoriesStorage}.ts</code>, <code>src/pages/tasks/utils/taskFilterUtils.ts</code>) and Mobile (<code>src/screens/content/{TaskListScreen,TaskKanbanScreen}.tsx</code>) components use semantic CSS variables / <code>dark:</code> Tailwind tokens and <code>useTheme()</code> tokens, supporting keyboard navigation (<code>Enter</code>/<code>Escape</code>/focus return) and mobile viewports.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surface (<code>brandhub-web</code>):</strong> <code>src/pages/tasks/components/{TaskFilterBar,TaskCategoryBar,TaskMultiSelectFilter}.tsx</code>, <code>src/pages/tasks/hooks/{useTaskFilters,useFilterCategoriesStorage}.ts</code>, <code>src/pages/tasks/utils/taskFilterUtils.ts</code></li><li><strong>Mobile Surface (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/content/{TaskListScreen,TaskKanbanScreen}.tsx</code></li><li><strong>Required UI States:</strong><ul><li><strong>Loading / Pending:</strong> Skeleton placeholders, progress indicators for uploads/imports, and disabled duplicate-submit triggers.</li><li><strong>Empty State:</strong> Clear localized explanation with role-appropriate CTA — never substituting synthetic mock items.</li><li><strong>Conflict / Warning:</strong> Preserves unsaved user drafts on <code>409</code> conflicts and surfaces inline warnings (such as <code>RAW</code> unedited photo badges or compliance warnings).</li><li><strong>Error / Retry:</strong> Actionable inline/banner error state with retry capability.</li></ul></li></ul><h2 id="_5-api-realtime-contract" tabindex="-1">5. API &amp; Realtime Contract <a class="header-anchor" href="#_5-api-realtime-contract" aria-label="Permalink to &quot;5. API &amp; Realtime Contract&quot;">​</a></h2><ul><li><strong>Endpoints / Channels:</strong> <code>GET /api/v1/workspaces/{workspaceId}/tasks?status=&amp;type=&amp;search=&amp;campaignId=&amp;from=&amp;to=&amp;assignee=&amp;due=&amp;sort=&amp;direction=&amp;page=&amp;size=</code></li><li><strong>Controllers (<code>brandhub-business-service</code>):</strong> <code>TaskController.getTasks()</code></li><li><strong>Services:</strong> <code>TaskServiceImpl, WorkspaceTaskReader (</code>TaskListQuery<code>)</code></li><li><strong>Repositories / Stores:</strong> TaskMongoRepository (MongoDB <code>tasks</code>)</li></ul><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Domain Error Codes:</strong> <code>400 VALIDATION_ERROR</code> (invalid ISO date / page bounds), <code>403 WORKSPACE_ACCESS_DENIED</code>.</li><li><strong>Audience &amp; Removed-Member Isolation:</strong> Removed or deactivated Workspace members lose read/write/WebSocket access immediately on the next request or STOMP frame; <code>Client</code> actors never see <code>INTERNAL</code>-only materials or other <code>ClientProfile</code> assets.</li><li><strong>Idempotency &amp; Concurrency:</strong> Optimistic revision checks (<code>workflowRevision</code>, <code>revision</code>, <code>clientMessageId</code>, <code>DriveOperationLease</code>) prevent race-condition overwrites and duplicate records on retry.</li></ul><h2 id="_7-definition-of-done-cross-references" tabindex="-1">7. Definition of Done &amp; Cross-References <a class="header-anchor" href="#_7-definition-of-done-cross-references" aria-label="Permalink to &quot;7. Definition of Done &amp; Cross-References&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Backend endpoints/handlers verified by automated tests (<a href="./test.html">test.md</a>), Web &amp; Mobile UI integrated against live APIs, <code>vi</code>/<code>en</code> locale parity verified, and Light/Dark themes verified.</li><li><strong>Out of Scope:</strong> Adjacent workflow capabilities covered by sibling FRs in <code>3.6.1–3.6.35</code> and social publishing execution in <code>3.8.1–3.8.15</code>.</li><li><strong>Related Documentation:</strong> <a href="./../../../../ba/05-content-task-workflow.html">BA Content &amp; Workflow Spec</a> · <a href="./../../../../ba/12-state-machines.html">State Machines</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a> · <a href="./test.html">Test Suite</a>.</li></ul>',18)])])}const h=t(r,[["render",i]]);export{m as __pageData,h as default};
